# NOTE: This file is generated from DocSpring's copy of OpenAPI Generator's connection.ex, which adds credentials,
# host and region from the environment. Do not edit this file manually.

defmodule Docspring.Connection do
  @moduledoc """
  Handle Tesla connections for Docspring.

  Additional middleware can be set in the compile-time or runtime configuration:

      config :tesla, Docspring.Connection,
        base_url: "https://sync.api.docspring.com/api/v2",
        adapter: Tesla.Adapter.Hackney

  The default base URL can also be set as:

      config :docspring,
        :base_url, "https://sync.api.docspring.com/api/v2"
  """

  @default_base_url Application.compile_env(
                      :docspring,
                      :base_url,
                      "https://sync.api.docspring.com/api/v2"
                    )

  @typedoc """
  The list of options that can be passed to new/1.

  - `base_url`: Overrides the base URL on a per-client basis.
  - `user_agent`: Overrides the User-Agent header.
  - `username`: A username for basic authentication.
  - `password`: A password for basic authentication.
  - `host`: Convenience option for providing a Docspring host (scheme optional).
  - `region`: Region code (e.g. `"US"`, `"EU"`) that selects the Docspring host.
  - `validate_requests`: `false` sends requests without checking them against the API's request schemas first
    (`Docspring.RequestValidator`). A request the API would reject returns `{:error, %Docspring.ValidationError{}}`.
  """
  @type options :: [
          {:base_url, String.t()},
          {:user_agent, String.t()},
          {:username, String.t() | nil},
          {:password, String.t() | nil},
          {:host, String.t()},
          {:region, String.t()},
          {:validate_requests, boolean()}
        ]

  @doc "Forward requests to Tesla."
  @spec request(Tesla.Client.t(), [Tesla.option()]) :: Tesla.Env.result()
  defdelegate request(client, options), to: Tesla

  @doc """
  Configure a Docspring client.

  Supports credentials supplied directly or via environment variables:

  * `DOCSPRING_TOKEN_ID`
  * `DOCSPRING_TOKEN_SECRET`

  Host resolution precedence:

  1. `options[:base_url]`
  2. `options[:host]`
  3. `DOCSPRING_HOST`
  4. `options[:region]`
  5. `DOCSPRING_REGION`

  Region values must be `"US"` or `"EU"` when provided.

  ### Parameters

  - `options`: an optional keyword list of Docspring.Connection.options.

  ### Returns

  Tesla.Env.client
  """
  @spec new(options) :: Tesla.Env.client()
  def new(options \\ []) do
    options
    |> resolve_env_defaults()
    |> middleware()
    |> Tesla.client(adapter())
  end

  @doc """
  Returns fully configured middleware for passing to Tesla.client/2.
  """
  @spec middleware(options) :: [Tesla.Client.middleware()]
  def middleware(options \\ []) do
    base_url =
      Keyword.get(
        options,
        :base_url,
        Application.get_env(:docspring, :base_url, @default_base_url)
      )

    tesla_options = Application.get_env(:tesla, __MODULE__, [])
    middleware = Keyword.get(tesla_options, :middleware, [])
    json_engine = Keyword.get(tesla_options, :json, JSON)

    user_agent =
      Keyword.get(
        options,
        :user_agent,
        Keyword.get(
          tesla_options,
          :user_agent,
          "docspring-elixir-4.3.0"
        )
      )

    username = Keyword.get(options, :username)
    password = Keyword.get(options, :password)

    middleware =
      if username || password do
        [{Tesla.Middleware.BasicAuth, %{username: username, password: password}} | middleware]
      else
        middleware
      end

    # After EncodeJson, so it checks the JSON the request sends
    middleware =
      if Keyword.get(options, :validate_requests, true) do
        [Docspring.RequestValidator | middleware]
      else
        middleware
      end

    [
      {Tesla.Middleware.BaseUrl, base_url},
      {Tesla.Middleware.Headers, [{"user-agent", user_agent}]},
      {Tesla.Middleware.EncodeJson, engine: json_engine}
      | middleware
    ]
  end

  @doc """
  Returns the default adapter for this API.
  """
  def adapter do
    :tesla
    |> Application.get_env(__MODULE__, [])
    |> Keyword.get(:adapter, nil)
  end

  defp resolve_env_defaults(options) do
    options
    |> maybe_put_username()
    |> maybe_put_password()
    |> maybe_put_base_url()
    |> Keyword.delete(:host)
    |> Keyword.delete(:region)
  end

  defp maybe_put_username(options), do: put_credential(options, :username, "DOCSPRING_TOKEN_ID")

  defp maybe_put_password(options),
    do: put_credential(options, :password, "DOCSPRING_TOKEN_SECRET")

  # Use the credential passed in, or the environment variable. An empty string counts as not set. Without credentials
  # the client is still created, and the API's 401 response says what's missing.
  defp put_credential(options, key, env_var) do
    case Keyword.get(options, key) do
      value when is_binary(value) and value != "" ->
        options

      _ ->
        case System.get_env(env_var) do
          value when is_binary(value) and value != "" -> Keyword.put(options, key, value)
          _ -> Keyword.delete(options, key)
        end
    end
  end

  defp maybe_put_base_url(options) do
    case Keyword.get(options, :base_url) do
      base_url when is_binary(base_url) ->
        if String.trim(base_url) == "" do
          set_resolved_base_url(options)
        else
          options
        end

      _ ->
        set_resolved_base_url(options)
    end
  end

  defp set_resolved_base_url(options) do
    case resolve_base_url(options) do
      nil -> Keyword.delete(options, :base_url)
      base_url -> Keyword.put(options, :base_url, base_url)
    end
  end

  defp resolve_base_url(options) do
    cond do
      host = host_value(Keyword.get(options, :host)) ->
        normalize_base_url(host)

      host = host_value(System.get_env("DOCSPRING_HOST")) ->
        normalize_base_url(host)

      true ->
        case resolve_region_host(options) do
          nil -> nil
          host -> normalize_base_url(host)
        end
    end
  end

  defp host_value(value) when is_binary(value) do
    case String.trim(value) do
      "" -> nil
      trimmed -> trimmed
    end
  end

  defp host_value(_), do: nil

  defp resolve_region_host(options) do
    region_source = Keyword.get(options, :region) || System.get_env("DOCSPRING_REGION")

    case region_source do
      region when is_binary(region) ->
        trimmed = String.trim(region)

        if trimmed == "" do
          nil
        else
          case String.upcase(trimmed) do
            "US" -> "sync.api.docspring.com"
            "EU" -> "sync.api-eu.docspring.com"
            _ -> raise ArgumentError, "#{region} is not a valid region. Valid regions: US, EU"
          end
        end

      _ ->
        nil
    end
  end

  defp normalize_base_url(host_or_url) do
    host_or_url
    |> ensure_scheme()
    |> ensure_api_path()
  end

  defp ensure_scheme(url) do
    cond do
      String.starts_with?(url, ["http://", "https://"]) -> url
      true -> "https://" <> url
    end
  end

  # Any API version's path (such as /api/v1 from a 3.x setup) becomes /api/v2
  defp ensure_api_path(url) do
    trimmed = String.trim_trailing(url, "/")
    Regex.replace(~r{/api/v\d+$}i, trimmed, "") <> "/api/v2"
  end
end
